import * as arc from "open-arc";

export type SolveFn = (puzzle: string) => Record<string, number> | undefined;

export const solveSpec = arc.defineRegion<SolveFn>({
  "id": "alphametics.solve",
  "intent": "Exercise \"alphametics\": implement `solve`.\n\nGiven an alphametics puzzle, find the correct solution.\n\n[Alphametics][alphametics] is a puzzle where letters in words are replaced with numbers.\n\nFor example `SEND + MORE = MONEY`:\n\n```text\n  S E N D\n  M O R E +\n-----------\nM O N E Y\n```\n\nReplacing these with valid numbers gives:\n\n```text\n  9 5 6 7\n  1 0 8 5 +\n-----------\n1 0 6 5 2\n```\n\nThis is correct because every letter is replaced by a different number and the words, translated into numbers, then make a valid sum.\n\nEach letter must represent a different digit, and the leading digit of a multi-digit number must not be zero.\n\n[alphametics]: https://en.wikipedia.org/wiki/Alphametics",
  "examples": [
    {
      "name": "Solve the alphametics puzzle > puzzle with three letters",
      "args": [
        "I + BB == ILL"
      ],
      "expected": {
        "I": 1,
        "B": 9,
        "L": 0
      }
    },
    {
      "name": "Solve the alphametics puzzle > puzzle with four letters",
      "args": [
        "AS + A == MOM"
      ],
      "expected": {
        "A": 9,
        "S": 2,
        "M": 1,
        "O": 0
      }
    },
    {
      "name": "Solve the alphametics puzzle > puzzle with six letters",
      "args": [
        "NO + NO + TOO == LATE"
      ],
      "expected": {
        "N": 7,
        "O": 4,
        "T": 9,
        "L": 1,
        "A": 0,
        "E": 2
      }
    }
  ]
});

// @openarc:begin alphametics.solve
export const solve: SolveFn = (puzzle) => arc.todo("alphametics.solve");
// @openarc:end alphametics.solve

export function solve(puzzle: string): Record<string, number> | undefined {
  // 1. Parse the puzzle string into words and the operator
  // Expected format: "WORD1 + WORD2 == RESULT" or "WORD1 + WORD2 + WORD3 == RESULT"
  const parts = puzzle.trim().split(/\s+/);
  if (parts.length < 3) return undefined;

  // Find the operator (== or +)
  let opIndex = -1;
  let op = "";
  for (let i = 0; i < parts.length; i++) {
    if (parts[i] === "==" || parts[i] === "+") {
      opIndex = i;
      op = parts[i];
      break;
    }
  }

  if (opIndex === -1) return undefined;

  const leftWords = parts.slice(0, opIndex).filter(w => w.length > 0);
  const rightWords = parts.slice(opIndex + 1).filter(w => w.length > 0);

  if (leftWords.length === 0 || rightWords.length === 0) return undefined;

  // 2. Extract all unique letters
  const letters = new Set<string>();
  const words = [...leftWords, ...rightWords];

  for (const word of words) {
    for (const char of word) {
      if (char >= 'A' && char <= 'Z') {
        letters.add(char);
      }
    }
  }

  const letterArray = Array.from(letters);
  if (letterArray.length > 10) return undefined; // Pigeonhole principle

  // 3. Identify leading letters (cannot be 0)
  const leadingLetters = new Set<string>();
  for (const word of words) {
    if (word.length > 1) {
      leadingLetters.add(word[0]);
    }
  }

  // 4. Prepare constraints
  // We need to map each letter to a digit 0-9
  // We will use backtracking to assign digits

  const usedDigits = new Set<number>();
  const letterToDigit = new Map<string, number>();

  // Helper to calculate value of a word
  const getWordValue = (word: string): number => {
    let value = 0;
    for (const char of word) {
      const digit = letterToDigit.get(char);
      if (digit === undefined) return -1; // Should not happen if we check before calling
      value = value * 10 + digit;
    }
    return value;
  };

  // Backtracking function
  const backtrack = (index: number): boolean => {
    if (index === letterArray.length) {
      // All letters assigned, check the equation
      const leftSum = leftWords.reduce((sum, word) => sum + getWordValue(word), 0);
      const rightSum = rightWords.reduce((sum, word) => sum + getWordValue(word), 0);

      if (leftSum === rightSum) {
        return true;
      }
      return false;
    }

    const letter = letterArray[index];

    // Try digits 0-9
    for (let digit = 0; digit <= 9; digit++) {
      // Check if digit already used
      if (usedDigits.has(digit)) continue;

      // Check if leading letter constraint is violated
      if (leadingLetters.has(letter) && digit === 0) continue;

      // Assign
      usedDigits.add(digit);
      letterToDigit.set(letter, digit);

      if (backtrack(index + 1)) return true;

      // Backtrack
      usedDigits.delete(digit);
      letterToDigit.delete(letter);
    }

    return false;
  };

  if (backtrack(0)) {
    return Object.fromEntries(letterToDigit);
  }

  return undefined;
}

