import * as arc from "open-arc";

export type EncodeFn = (plainText: string) => string;

export const encodeSpec = arc.defineRegion<EncodeFn>({
  "id": "atbashCipher.encode",
  "intent": "Exercise \"atbash-cipher\": implement `encode`.\n\nCreate an implementation of the Atbash cipher, an ancient encryption system created in the Middle East.\n\nThe Atbash cipher is a simple substitution cipher that relies on transposing all the letters in the alphabet such that the resulting alphabet is backwards.\nThe first letter is replaced with the last letter, the second with the second-last, and so on.\n\nAn Atbash cipher for the Latin alphabet would be as follows:\n\n```text\nPlain:  abcdefghijklmnopqrstuvwxyz\nCipher: zyxwvutsrqponmlkjihgfedcba\n```\n\nIt is a very weak cipher because it only has one possible key, and it is a simple mono-alphabetic substitution cipher.\nHowever, this may not have been an issue in the cipher's time.\n\nCiphertext is written out in groups of fixed length, the traditional group size being 5 letters, leaving numbers unchanged, and punctuation is excluded.\nThis is to make it harder to guess things based on word boundaries.\nAll text will be encoded as lowercase letters.\n\n## Examples\n\n- Encoding `test` gives `gvhg`\n- Encoding `x123 yes` gives `c123b vh`\n- Decoding `gvhg` gives `test`\n- Decoding `gsvjf rxpyi ldmul cqfnk hlevi gsvoz abwlt` gives `thequickbrownfoxjumpsoverthelazydog`",
  "examples": [
    {
      "name": "AtbashCipher > encoding > encode yes",
      "args": [
        "yes"
      ],
      "expected": "bvh"
    },
    {
      "name": "AtbashCipher > encoding > encode no",
      "args": [
        "no"
      ],
      "expected": "ml"
    },
    {
      "name": "AtbashCipher > encoding > encode OMG",
      "args": [
        "OMG"
      ],
      "expected": "lnt"
    }
  ]
});

// @openarc:begin atbashCipher.encode
export const encode: EncodeFn = (plainText) => {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const map = new Map();
  for (let i = 0; i < alphabet.length; i++) {
    map.set(alphabet[i], alphabet[alphabet.length - 1 - i]);
  }
  const clean = plainText.toLowerCase().replace(/[^a-z0-9]/g, '');
  let result = '';
  for (const char of clean) {
    if (map.has(char)) {
      result += map.get(char);
    } else {
      result += char;
    }
  }
  return result.replace(/(.{1,5})/g, '$1 ').trim();
};
// @openarc:end atbashCipher.encode

export type DecodeFn = (cipherText: string) => string;

export const decodeSpec = arc.defineRegion<DecodeFn>({
  "id": "atbashCipher.decode",
  "intent": "Exercise \"atbash-cipher\": implement `decode`.\n\nCreate an implementation of the Atbash cipher, an ancient encryption system created in the Middle East.\n\nThe Atbash cipher is a simple substitution cipher that relies on transposing all the letters in the alphabet such that the resulting alphabet is backwards.\nThe first letter is replaced with the last letter, the second with the second-last, and so on.\n\nAn Atbash cipher for the Latin alphabet would be as follows:\n\n```text\nPlain:  abcdefghijklmnopqrstuvwxyz\nCipher: zyxwvutsrqponmlkjihgfedcba\n```\n\nIt is a very weak cipher because it only has one possible key, and it is a simple mono-alphabetic substitution cipher.\nHowever, this may not have been an issue in the cipher's time.\n\nCiphertext is written out in groups of fixed length, the traditional group size being 5 letters, leaving numbers unchanged, and punctuation is excluded.\nThis is to make it harder to guess things based on word boundaries.\nAll text will be encoded as lowercase letters.\n\n## Examples\n\n- Encoding `test` gives `gvhg`\n- Encoding `x123 yes` gives `c123b vh`\n- Decoding `gvhg` gives `test`\n- Decoding `gsvjf rxpyi ldmul cqfnk hlevi gsvoz abwlt` gives `thequickbrownfoxjumpsoverthelazydog`",
  "examples": [
    {
      "name": "AtbashCipher > decode > decode exercism",
      "args": [
        "vcvix rhn"
      ],
      "expected": "exercism"
    },
    {
      "name": "AtbashCipher > decode > decode a sentence",
      "args": [
        "zmlyh gzxov rhlug vmzhg vkkrm thglm v"
      ],
      "expected": "anobstacleisoftenasteppingstone"
    }
  ]
});

// @openarc:begin atbashCipher.decode
export const decode: DecodeFn = (cipherText) => {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const map = new Map();
  for (let i = 0; i < alphabet.length; i++) {
    map.set(alphabet[i], alphabet[alphabet.length - 1 - i]);
  }
  const clean = cipherText.toLowerCase().replace(/[^a-z0-9]/g, '');
  let result = '';
  for (const char of clean) {
    if (map.has(char)) {
      result += map.get(char);
    } else {
      result += char;
    }
  }
  return result;
};
// @openarc:end atbashCipher.decode

export function encode(plainText: string): string {
  const alphabet = "abcdefghijklmnopqrstuvwxyz";
  const map = new Map<string, string>();

  for (let i = 0; i < alphabet.length; i++) {
    map.set(alphabet[i], alphabet[alphabet.length - 1 - i]);
  }

  let result = "";
  let count = 0;

  for (const char of plainText.toLowerCase()) {
    if (char >= "a" && char <= "z") {
      if (count > 0 && count % 5 === 0) {
        result += " ";
      }
      result += map.get(char)!;
      count++;
    } else if (char >= "0" && char <= "9") {
      if (count > 0 && count % 5 === 0) {
        result += " ";
      }
      result += char;
      count++;
    }
    // Ignore punctuation and whitespace
  }

  return result;
}

export function decode(cipherText: string): string {
  const alphabet = "abcdefghijklmnopqrstuvwxyz";
  const map = new Map<string, string>();

  for (let i = 0; i < alphabet.length; i++) {
    map.set(alphabet[i], alphabet[alphabet.length - 1 - i]);
  }

  let result = "";

  for (const char of cipherText.toLowerCase()) {
    if (char >= "a" && char <= "z") {
      result += map.get(char)!;
    } else if (char >= "0" && char <= "9") {
      result += char;
    }
    // Ignore spaces and punctuation
  }

  return result;
}

import * as arc from "open-arc";

export type HeyFn = (message: string) => string;

export const heySpec = arc.defineRegion<HeyFn>({
  "id": "bob.hey",
  "intent": "Exercise \"bob\": implement `hey`.\n\nYour task is to determine what Bob will reply to someone when they say something to him or ask him a question.\n\nBob only ever answers one of five things:\n\n- **\"Sure.\"**\n  This is his response if you ask him a question, such as \"How are you?\"\n  The convention used for questions is that it ends with a question mark.\n- **\"Whoa, chill out!\"**\n  This is his answer if you YELL AT HIM.\n  The convention used for yelling is ALL CAPITAL LETTERS.\n- **\"Calm down, I know what I'm doing!\"**\n  This is what he says if you yell a question at him.\n- **\"Fine. Be that way!\"**\n  This is how he responds to silence.\n  The convention used for silence is nothing, or various combinations of whitespace characters.\n- **\"Whatever.\"**\n  This is what he answers to anything else.",
  "examples": [
    {
      "name": "Bob > stating something",
      "args": [
        "Tom-ay-to, tom-aaaah-to."
      ],
      "expected": "Whatever."
    },
    {
      "name": "Bob > shouting",
      "args": [
        "WATCH OUT!"
      ],
      "expected": "Whoa, chill out!"
    },
    {
      "name": "Bob > shouting gibberish",
      "args": [
        "FCECDFCAAB"
      ],
      "expected": "Whoa, chill out!"
    }
  ]
});

// @openarc:begin bob.hey
export const hey: HeyFn = (message) => {
  const trimmed = message.trim();
    if (trimmed === '') return 'Fine. Be that way!';
    const isQuestion = trimmed.endsWith('?');
    const hasLetters = /[a-zA-Z]/.test(trimmed);
    const isYelling = hasLetters && trimmed === trimmed.toUpperCase();
    if (isYelling && isQuestion) return 'Calm down, I know what I\'m doing!';
    if (isYelling) return 'Whoa, chill out!';
    if (isQuestion) return 'Sure.';
    return 'Whatever.';
};
// @openarc:end bob.hey

export function hey(message: string): string {
  const trimmed = message.trim();

  // Check for silence
  if (trimmed === "") {
    return "Fine. Be that way!";
  }

  const isQuestion = trimmed.endsWith("?");
  const hasLetters = /[a-zA-Z]/.test(trimmed);
  const isYelling = hasLetters && trimmed === trimmed.toUpperCase();

  // Determine the response based on the rules
  if (isYelling && isQuestion) {
    return "Calm down, I know what I'm doing!";
  } else if (isYelling) {
    return "Whoa, chill out!";
  } else if (isQuestion) {
    return "Sure.";
  } else {
    return "Whatever.";
  }
}

import * as arc from "open-arc";

export type Legacy = Record<string, string[]>;

export type TransformFn = (old: Legacy) => Record<string, number>;

export const transformSpec = arc.defineRegion<TransformFn>({
  "id": "etl.transform",
  "intent": "Exercise \"etl\": implement `transform`.\n\nYour task is to change the data format of letters and their point values in the game.\n\nCurrently, letters are stored in groups based on their score, in a one-to-many mapping.\n\n- 1 point: \"A\", \"E\", \"I\", \"O\", \"U\", \"L\", \"N\", \"R\", \"S\", \"T\",\n- 2 points: \"D\", \"G\",\n- 3 points: \"B\", \"C\", \"M\", \"P\",\n- 4 points: \"F\", \"H\", \"V\", \"W\", \"Y\",\n- 5 points: \"K\",\n- 8 points: \"J\", \"X\",\n- 10 points: \"Q\", \"Z\",\n\nThis needs to be changed to store each individual letter with its score in a one-to-one mapping.\n\n- \"a\" is worth 1 point.\n- \"b\" is worth 3 points.\n- \"c\" is worth 3 points.\n- \"d\" is worth 2 points.\n- etc.\n\nAs part of this change, the team has also decided to change the letters to be lower-case rather than upper-case.\n\n~~~~exercism/note\nIf you want to look at how the data was previously structured and how it needs to change, take a look at the examples in the test suite.\n~~~~",
  "examples": [
    {
      "name": "Transform > transforms one value",
      "args": [
        {
          "1": [
            "A"
          ]
        }
      ],
      "expected": {
        "a": 1
      }
    },
    {
      "name": "Transform > transforms more values",
      "args": [
        {
          "1": [
            "A",
            "E",
            "I",
            "O",
            "U"
          ]
        }
      ],
      "expected": {
        "a": 1,
        "e": 1,
        "i": 1,
        "o": 1,
        "u": 1
      }
    }
  ]
});

// @openarc:begin etl.transform
export const transform: TransformFn = (old) => {
  const scoreMap: Record<string, number> = {
    'a': 1, 'b': 3, 'c': 3, 'd': 2, 'e': 1,
    'f': 4, 'g': 2, 'h': 4, 'i': 1, 'j': 8,
    'k': 5, 'l': 1, 'm': 3, 'n': 1, 'o': 1,
    'p': 3, 'q': 10, 'r': 1, 's': 1, 't': 1,
    'u': 1, 'v': 4, 'w': 4, 'x': 8, 'y': 4,
    'z': 10
  };

  const result: Record<string, number> = {};
  for (const [score, letters] of Object.entries(old)) {
    const points = Number(score);
    for (const letter of letters) {
      result[letter.toLowerCase()] = points;
    }
  }
  return result;
};
// @openarc:end etl.transform

export type Legacy = Record<string, string[]>;

export function transform(old: Legacy): Record<string, number> {
  const result: Record<string, number> = {};

  for (const [score, letters] of Object.entries(old)) {
    for (const letter of letters) {
      result[letter.toLowerCase()] = Number(score);
    }
  }

  return result;
}

export function verse(n: number): string[] {
  if (Number.isNaN(n) || n < 1 || n > 12) {
    throw new Error("Invalid verse number");
  }

  const data: { subject: string; verb: string }[] = [
    { subject: "the house that Jack built", verb: "" },
    { subject: "the malt", verb: "that lay in" },
    { subject: "the rat", verb: "that ate" },
    { subject: "the cat", verb: "that killed" },
    { subject: "the dog", verb: "that worried" },
    { subject: "the cow with the crumpled horn", verb: "that tossed" },
    { subject: "the maiden all forlorn", verb: "that milked" },
    { subject: "the man all tattered and torn", verb: "that kissed" },
    { subject: "the priest all shaven and shorn", verb: "that married" },
    { subject: "the rooster that crowed in the morn", verb: "that woke" },
    { subject: "the farmer sowing his corn", verb: "that kept" },
    { subject: "the horse and the hound and the horn", verb: "that belonged to" },
  ];

  const lines: string[] = [];
  for (let i = n - 1; i >= 0; i--) {
    if (i === 0) {
      lines.push(`This is ${data[i].subject}.`);
    } else {
      lines.push(`This is ${data[i].subject}`);
      lines.push(`${data[i].verb} ${data[i - 1].subject}`);
    }
  }

  return lines;
}

export function verses(start: number, end: number): string[] {
  if (Number.isNaN(start) || Number.isNaN(end) || start < 1 || end > 12 || start > end) {
    throw new Error("Invalid verse range");
  }

  const result: string[] = [];
  for (let i = start; i <= end; i++) {
    result.push(...verse(i));
    if (i < end) {
      result.push("");
    }
  }

  return result;
}

import * as arc from "open-arc";

export interface Item { weight: number; value: number }

export type MaximumValueFn = (input: { maximumWeight: number; items: Item[] }) => number;

export const maximumValueSpec = arc.defineRegion<MaximumValueFn>({
  "id": "knapsack.maximumValue",
  "intent": "Exercise \"knapsack\": implement `maximumValue`.\n\nYour task is to determine which items to take so that the total value of her selection is maximized, taking into account the knapsack's carrying capacity.\n\nItems will be represented as a list of items.\nEach item will have a weight and value.\nAll values given will be strictly positive.\nLhakpa can take only one of each item.\n\nFor example:\n\n```text\nItems: [\n  { \"weight\": 5, \"value\": 10 },\n  { \"weight\": 4, \"value\": 40 },\n  { \"weight\": 6, \"value\": 30 },\n  { \"weight\": 4, \"value\": 50 }\n]\n\nKnapsack Maximum Weight: 10\n```\n\nFor the above, the first item has weight 5 and value 10, the second item has weight 4 and value 40, and so on.\nIn this example, Lhakpa should take the second and fourth item to maximize her value, which, in this case, is 90.\nShe cannot get more than 90 as her knapsack has a weight limit of 10.",
  "examples": [
    {
      "name": "Check if max carriable value is returned > No items",
      "args": [
        {
          "maximumWeight": 100,
          "items": []
        }
      ],
      "expected": 0
    },
    {
      "name": "Check if max carriable value is returned > One item, but too heavy",
      "args": [
        {
          "maximumWeight": 10,
          "items": [
            {
              "weight": 100,
              "value": 1
            }
          ]
        }
      ],
      "expected": 0
    },
    {
      "name": "Check if max carriable value is returned > Five items. Can't be greedy by weight",
      "args": [
        {
          "maximumWeight": 10,
          "items": [
            {
              "weight": 2,
              "value": 5
            },
            {
              "weight": 2,
              "value": 5
            },
            {
              "weight": 2,
              "value": 5
            },
            {
              "weight": 2,
              "value": 5
            },
            {
              "weight": 10,
              "value": 21
            }
          ]
        }
      ],
      "expected": 21
    }
  ]
});

// @openarc:begin knapsack.maximumValue
export const maximumValue: MaximumValueFn = (input) => {
  const { items, maximumWeight } = input;
  const n = items.length;
  if (n === 0) return 0;
  const W = maximumWeight;
  const dp = Array.from({ length: n + 1 }, () => Array(W + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    const item = items[i - 1];
    for (let w = 0; w <= W; w++) {
      dp[i][w] = dp[i - 1][w];
      if (item.weight <= w) {
        dp[i][w] = Math.max(dp[i][w], dp[i - 1][w - item.weight] + item.value);
      }
    }
  }
  return dp[n][W];
};
// @openarc:end knapsack.maximumValue

export interface Item { weight: number; value: number }

export function maximumValue(input: { maximumWeight: number; items: Item[] }): number {
  const { maximumWeight, items } = input;

  // Handle edge cases
  if (maximumWeight <= 0 || items.length === 0) {
    return 0;
  }

  const n = items.length;
  // dp[i][w] represents the maximum value achievable with the first i items and weight limit w
  // We use a 1D array to optimize space complexity to O(maximumWeight)
  const dp = new Array(maximumWeight + 1).fill(0);

  for (const item of items) {
    const weight = item.weight;
    const value = item.value;

    // Traverse backwards to avoid using the same item multiple times for the same weight limit in one iteration
    for (let w = maximumWeight; w >= weight; w--) {
      dp[w] = Math.max(dp[w], dp[w - weight] + value);
    }
  }

  return dp[maximumWeight];
}

