// @openarc:begin runLengthEncoding.encode
export const encode: EncodeFn = (plain) => {
  let result = '';
    let count = 0;
    let prev = '';
    for (const char of plain) {
      if (char === prev) {
        count++;
      } else {
        if (prev !== '') {
          result += count > 1 ? `${count}${prev}` : prev;
        }
        prev = char;
        count = 1;
      }
    }
    if (prev !== '') {
      result += count > 1 ? `${count}${prev}` : prev;
    }
    return result;
};
// @openarc:end runLengthEncoding.encode

