      "name": "Secret Handshake > Create A Handshake For A Number > double blink for 10",
      "args": [
        2
      ],
      "expected": [
        "double blink"
      ]
    },
    {
      "name": "Secret Handshake > Create A Handshake For A Number > close your eyes for 100",
