// @openarc:begin secretHandshake.commands
export const commands: CommandsFn = (n) => {
  const actions: string[] = [];
  if (n & 1) actions.push('wink');
  if (n & 2) actions.push('double blink');
  if (n & 4) actions.push('close your eyes');
  if (n & 8) actions.push('jump');
  if (n & 16) actions.reverse();
  return actions;
};
// @openarc:end secretHandshake.commands

export function commands(n: number): string[] {
  const actions = [
    "wink",
    "double blink",
    "close your eyes",
    "jump",
  ];

  const result: string[] = [];

  // Check bits 0 to 3 for actions
  if (n & 1) result.push(actions[0]);
  if (n & 2) result.push(actions[1]);
  if (n & 4) result.push(actions[2]);
  if (n & 8) result.push(actions[3]);

  // Check bit 4 for reverse
  if (n & 16) {
    result.reverse();
  }

  return result;
}

