import * as arc from "open-arc";

export type SolveFn = (puzzle: string) => Record<string, number> | undefined;

export const solveSpec = arc.defineRegion<SolveFn>({
  "id": "alphametics.solve",
  "intent": "Exercise \"alphametics\": implement `solve`.\n\nGiven an alphametics puzzle, find the correct solution.\n\n[Alphametics][alphametics] is a puzzle where letters in words are replaced with numbers.\n\nFor example `SEND + MORE = MONEY`:\n\n```text\n  S E N D\n  M O R E +\n-----------\nM O N E Y\n```\n\nReplacing these with valid numbers gives:\n\n```text\n  9 5 6 7\n  1 0 8 5 +\n-----------\n1 0 6 5 2\n```\n\nThis is correct because every letter is replaced by a different number and the words, translated into numbers, then make a valid sum.\n\nEach letter must represent a different digit, and the leading digit of a multi-digit number must not be zero.\n\n[alphametics]: https://en.wikipedia.org/wiki/Alphametics",
  "examples": [
    {
      "name": "Solve the alphametics puzzle > puzzle with three letters",
      "args": [
        "I + BB == ILL"
      ],
      "expected": {
        "I": 1,
        "B": 9,
        "L": 0
      }
    },
    {
      "name": "Solve the alphametics puzzle > puzzle with four letters",
      "args": [
        "AS + A == MOM"
      ],
      "expected": {
        "A": 9,
        "S": 2,
        "M": 1,
        "O": 0
      }
    },
    {
      "name": "Solve the alphametics puzzle > puzzle with six letters",
      "args": [
        "NO + NO + TOO == LATE"
      ],
      "expected": {
        "N": 7,
        "O": 4,
        "T": 9,
        "L": 1,
        "A": 0,
        "E": 2
      }
    }
  ]
});

// @openarc:begin alphametics.solve
export const solve: SolveFn = (puzzle) => arc.todo("alphametics.solve");
// @openarc:end alphametics.solve

export function solve(puzzle: string): Record<string, number> | undefined {
  // 1. Parse the puzzle string into words and the operator
  // Expected format: "WORD1 + WORD2 == RESULT" or "WORD1 + WORD2 + WORD3 == RESULT"
  const parts = puzzle.trim().split(/\s+/);
  if (parts.length < 3) return undefined;

  // Find the operator (== or +)
  let opIndex = -1;
  let op = "";
  for (let i = 0; i < parts.length; i++) {
    if (parts[i] === "==" || parts[i] === "+") {
      opIndex = i;
      op = parts[i];
      break;
    }
  }

  if (opIndex === -1) return undefined;

  const leftWords = parts.slice(0, opIndex).filter(w => w.length > 0);
  const rightWords = parts.slice(opIndex + 1).filter(w => w.length > 0);

  if (leftWords.length === 0 || rightWords.length === 0) return undefined;

  // 2. Extract all unique letters
  const letters = new Set<string>();
  const words = [...leftWords, ...rightWords];

  for (const word of words) {
    for (const char of word) {
      if (char >= 'A' && char <= 'Z') {
        letters.add(char);
      }
    }
  }

  const letterArray = Array.from(letters);
  const n = letterArray.length;

  if (n > 10) return undefined; // More letters than digits

  // 3. Identify leading letters (cannot be 0)
  const leadingLetters = new Set<string>();
  for (const word of words) {
    if (word.length > 1) {
      leadingLetters.add(word[0]);
    }
  }

  // 4. Prepare constraints
  // We need to map each letter to a digit 0-9
  // We will use backtracking to assign digits

  // Pre-calculate powers of 10 for each word to compute value quickly
  // value = sum(digit * 10^position)
  const wordValues: number[][] = [];
  for (const word of words) {
    const powers: number[] = [];
    let p = 1;
    for (let i = word.length - 1; i >= 0; i--) {
      powers.push(p);
      p *= 10;
    }
    wordValues.push(powers);
  }

  // 5. Backtracking solver
  // We need to assign digits to letters such that:
  // sum(leftWords) == sum(rightWords)

  // Create a mapping from letter to index in letterArray
  const letterToIndex = new Map<string, number>();
  for (let i = 0; i < n; i++) {
    letterToIndex.set(letterArray[i], i);
  }

  // Create a mapping from index to letter
  const indexToLetter = letterArray;

  // Used digits mask
  let usedDigits = 0;

  // Solution array
  const solution: number[] = new Array(n);

  // Helper to check if a digit assignment is valid for leading letters
  function isLeadingValid(letter: string, digit: number): boolean {
    if (digit === 0 && leadingLetters.has(letter)) {
      return false;
    }
    return true;
  }

  // Recursive backtracking function
  function backtrack(idx: number): boolean {
    if (idx === n) {
      // All letters assigned, check the equation
      let leftSum = 0;
      for (const word of leftWords) {
        let wordVal = 0;
        const powers = wordValues[leftWords.indexOf(word)];
        for (let i = 0; i < word.length; i++) {
          const letter = word[i];
          const digit = solution[letterToIndex.get(letter)!];
          wordVal += digit * powers[i];
        }
        leftSum += wordVal;
      }

      let rightSum = 0;
      for (const word of rightWords) {
        let wordVal = 0;
        const powers = wordValues[rightWords.indexOf(word)];
        for (let i = 0; i < word.length; i++) {
          const letter = word[i];
          const digit = solution[letterToIndex.get(letter)!];
          wordVal += digit * powers[i];
        }
        rightSum += wordVal;
      }

      return leftSum === rightSum;
    }

    const letter = indexToLetter[idx];

    // Try each digit
    for (let d = 0; d <= 9; d++) {
      // Check if digit is already used
      if ((usedDigits & (1 << d))) continue;

      // Check if digit is valid for leading letter
      if (!isLeadingValid(letter, d)) continue;

      // Assign digit
      solution[idx] = d;
      usedDigits |= (1 << d);

      if (backtrack(idx + 1)) {
        return true;
      }

      // Backtrack
      solution[idx] = -1;
      usedDigits &= ~(1 << d);
    }

    return false;
  }

  if (backtrack(0)) {
    const result: Record<string, number> = {};
    for (let i = 0; i < n; i++) {
      result[letterArray[i]] = solution[i];
    }
    return result;
  }

  return undefined;
}

