export const encode: EncodeFn = (plainText) => {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const map = new Map();
  for (let i = 0; i < alphabet.length; i++) {
    map.set(alphabet[i], alphabet[alphabet.length - 1 - i]);
  }
  const clean = plainText.toLowerCase().replace(/[^a-z0-9]/g, '');
  let result = '';
  for (const char of clean) {
    if (map.has(char)) {
      result += map.get(char);
    } else {
      result += char;
    }
  }
  return result.replace(/(.{1,5})/g, '$1 ').trim();
};
