// @openarc:begin largestSeriesProduct.largestProduct
export const largestProduct: LargestProductFn = (digits, span) => {
  if (span < 0) throw new Error('span must not be negative');
  if (span > digits.length) throw new Error('span must be smaller than string length');
  if (/[^0-9]/.test(digits)) throw new Error('digits input must only contain digits');
  if (span === 0) return 1;
  let maxProduct = 0;
  for (let i = 0; i <= digits.length - span; i++) {
    let product = 1;
    for (let j = 0; j < span; j++) {
      product *= parseInt(digits[i + j], 10);
    }
    if (product > maxProduct) {
      maxProduct = product;
    }
  }
  return maxProduct;
};
// @openarc:end largestSeriesProduct.largestProduct

export function largestProduct(digits: string, span: number): number {
  // Validate span
  if (span < 0) {
    throw new Error("span must not be negative");
  }

  // If span is 0, the product of an empty series is defined as 1
  if (span === 0) {
    return 1;
  }

  // Validate digits string
  if (digits === undefined) {
    throw new Error("digits must be a string");
  }

  if (typeof digits !== "string") {
    throw new Error("digits must be a string");
  }

  // Check for non-digit characters
  if (/[^0-9]/.test(digits)) {
    throw new Error("digits input must only contain digits");
  }

  // Check if span is larger than the length of the digits string
  if (span > digits.length) {
    throw new Error("span must be smaller than string length");
  }

  let maxProduct = 0;

  // Iterate through the string with a sliding window of size 'span'
  for (let i = 0; i <= digits.length - span; i++) {
    let currentProduct = 1;

    // Calculate product for the current series
    for (let j = 0; j < span; j++) {
      currentProduct *= parseInt(digits[i + j], 10);
    }

    // Update maxProduct if currentProduct is larger
    if (currentProduct > maxProduct) {
      maxProduct = currentProduct;
    }
  }

  return maxProduct;
}

