// @openarc:begin nucleotideCount.nucleotideCounts
export const nucleotideCounts: NucleotideCountsFn = (strand) => {
  const counts: NucleotideCounts = { A: 0, C: 0, G: 0, T: 0 };
  for (const char of strand) {
    if (char === 'A') counts.A++;
    else if (char === 'C') counts.C++;
    else if (char === 'G') counts.G++;
    else if (char === 'T') counts.T++;
    else throw new Error('Invalid nucleotide in strand');
  }
  return counts;
};
// @openarc:end nucleotideCount.nucleotideCounts

export interface NucleotideCounts { A: number; C: number; G: number; T: number }

export function nucleotideCounts(strand: string): NucleotideCounts {
  const counts: NucleotideCounts = { A: 0, C: 0, G: 0, T: 0 };

  for (const char of strand) {
    switch (char) {
      case 'A':
        counts.A++;
        break;
      case 'C':
        counts.C++;
        break;
      case 'G':
        counts.G++;
        break;
      case 'T':
        counts.T++;
        break;
      default:
        throw new Error(`Invalid nucleotide: ${char}`);
    }
  }

  return counts;
}

