// @openarc:begin perfectNumbers.classify
export const classify: ClassifyFn = (n) => {
  if (n <= 0) throw new Error('Classification is only possible for natural numbers.');
  const sum = (n: number): number => {
    let s = 0;
    for (let i = 1; i <= n / 2; i++) {
      if (n % i === 0) s += i;
    }
    return s;
  };
  const aliquot = sum(n);
  if (aliquot === n) return 'perfect';
  if (aliquot > n) return 'abundant';
  return 'deficient';
};
// @openarc:end perfectNumbers.classify

export function classify(n: number): 'perfect' | 'abundant' | 'deficient' {
  if (!Number.isInteger(n) || n <= 0) {
    throw new Error("Classification is only possible for natural numbers.");
  }

  if (n === 1) {
    return 'deficient';
  }

  let aliquotSum = 1;
  const limit = Math.sqrt(n);

  for (let i = 2; i <= limit; i++) {
    if (n % i === 0) {
      aliquotSum += i;
      const paired = n / i;
      if (paired !== i) {
        aliquotSum += paired;
      }
    }
  }

  if (aliquotSum === n) {
    return 'perfect';
  } else if (aliquotSum > n) {
    return 'abundant';
  } else {
    return 'deficient';
  }
}

