// @openarc:begin rotationalCipher.rotate
export const rotate: RotateFn = (text, shift) => {
  return text.split('').map(char => {
      if (char >= 'a' && char <= 'z') {
        return String.fromCharCode(((char.charCodeAt(0) - 97 + shift) % 26) + 97);
      }
      if (char >= 'A' && char <= 'Z') {
        return String.fromCharCode(((char.charCodeAt(0) - 65 + shift) % 26) + 65);
      }
      return char;
    }).join('');
};
// @openarc:end rotationalCipher.rotate

export function rotate(text: string, shift: number): string {
  // Normalize the shift to be within 0-25 range
  const normalizedShift = ((shift % 26) + 26) % 26;

  return text.split("").map((char) => {
    // Check if the character is an uppercase letter
    if (char >= "A" && char <= "Z") {
      const base = "A".charCodeAt(0);
      const code = char.charCodeAt(0);
      const offset = code - base;
      const newOffset = (offset + normalizedShift) % 26;
      return String.fromCharCode(base + newOffset);
    }

    // Check if the character is a lowercase letter
    if (char >= "a" && char <= "z") {
      const base = "a".charCodeAt(0);
      const code = char.charCodeAt(0);
      const offset = code - base;
      const newOffset = (offset + normalizedShift) % 26;
      return String.fromCharCode(base + newOffset);
    }

    // If it's not a letter, return it unchanged
    return char;
  }).join("");
}

