// @openarc:begin saddlePoints.saddlePoints
export const saddlePoints: SaddlePointsFn = (matrix) => {
  const rows = matrix.length;
  if (rows === 0) return [];
  const cols = matrix[0].length;
  if (cols === 0) return [];
  const result: Point[] = [];
  for (let r = 0; r < rows; r++) {
    const rowMax = Math.max(...matrix[r]);
    for (let c = 0; c < cols; c++) {
      if (matrix[r][c] === rowMax) {
        let colMin = matrix[0][c];
        for (let i = 0; i < rows; i++) {
          if (matrix[i][c] < colMin) colMin = matrix[i][c];
        }
        if (matrix[r][c] === colMin) {
          result.push({ row: r + 1, column: c + 1 });
        }
      }
    }
  }
  return result;
};
// @openarc:end saddlePoints.saddlePoints

export interface Point { row: number; column: number }

export function saddlePoints(matrix: number[][]): Point[] {
  const result: Point[] = [];

  // Handle empty matrix case: return empty array instead of throwing
  if (matrix.length === 0) {
    return result;
  }

  const numRows = matrix.length;
  const numCols = matrix[0].length;

  // Check for empty rows or inconsistent column lengths
  for (let i = 0; i < numRows; i++) {
    if (matrix[i].length !== numCols || matrix[i].length === 0) {
      throw new Error("Invalid matrix");
    }
  }

  // Precompute max for each row
  const rowMaxs = matrix.map((row) => Math.max(...row));

  // Iterate through each cell
  for (let row = 0; row < numRows; row++) {
    for (let col = 0; col < numCols; col++) {
      const value = matrix[row][col];

      // Check if it is the largest in its row
      if (value !== rowMaxs[row]) {
        continue;
      }

      // Check if it is the smallest in its column
      let isMinInCol = true;
      for (let r = 0; r < numRows; r++) {
        if (matrix[r][col] < value) {
          isMinInCol = false;
          break;
        }
      }

      if (isMinInCol) {
        result.push({ row: row + 1, column: col + 1 });
      }
    }
  }

  return result;
}

