// @openarc:begin say.sayInEnglish
export const sayInEnglish: SayInEnglishFn = (n) => {
  if (n < 0 || n > 999999999999) {
      throw new Error('Number out of range');
    }
  if (n === 0) return 'zero';
  const ones = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'];
  const teens = ['ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
  const tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
  const scales = ['', 'thousand', 'million', 'billion'];
  const convert = (num: number): string => {
      if (num === 0) return '';
      if (num < 10) return ones[num];
      if (num < 20) return teens[num - 10];
      if (num < 100) return tens[Math.floor(num / 10)] + (num % 10 !== 0 ? '-' + ones[num % 10] : '');
      if (num < 1000) return ones[Math.floor(num / 100)] + 'hundred' + (num % 100 !== 0 ? ' ' + convert(num % 100) : '');
      return '';
    };
  let result = '';
  let scaleIndex = 0;
  while (n > 0) {
      const chunk = n % 1000;
      if (chunk > 0) {
        const chunkStr = convert(chunk);
        const scale = scales[scaleIndex];
        if (scale) {
          result = chunkStr + ' ' + scale + (result ? ' ' + result : '');
        } else {
          result = chunkStr + (result ? ' ' + result : '');
        }
      }
      n = Math.floor(n / 1000);
      scaleIndex++;
    }
  return result;
};
// @openarc:end say.sayInEnglish

export function sayInEnglish(n: number): string {
  // Validate input range: 0 to 999,999,999,999 (trillions)
  if (!Number.isInteger(n)) {
    throw new Error("Input must be an integer.");
  }
  if (n < 0 || n > 999_999_999_999) {
    throw new Error("Input must be between 0 and 999,999,999,999.");
  }

  // Handle zero explicitly
  if (n === 0) {
    return "zero";
  }

  // Define word mappings
  const ones = [
    "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
    "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
    "seventeen", "eighteen", "nineteen"
  ];

  const tens = [
    "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
  ];

  const scales = ["", "thousand", "million", "billion"];

  // Helper to convert a number less than 1000 to words
  function convertUnder1000(num: number): string {
    if (num === 0) return "";

    let result = "";

    // Handle hundreds
    if (num >= 100) {
      result += ones[Math.floor(num / 100)] + " hundred";
      num %= 100;
      if (num > 0) result += " ";
    }

    // Handle tens and ones
    if (num >= 20) {
      result += tens[Math.floor(num / 10)];
      if (num % 10 > 0) {
        result += "-" + ones[num % 10];
      }
    } else if (num > 0) {
      result += ones[num];
    }

    return result;
  }

  // Break the number into chunks of thousands
  const chunks: number[] = [];
  let tempN = n;
  while (tempN > 0) {
    chunks.push(tempN % 1000);
    tempN = Math.floor(tempN / 1000);
  }

  // Convert each chunk to words and attach scale
  const parts: string[] = [];
  for (let i = 0; i < chunks.length; i++) {
    const chunk = chunks[i];
    if (chunk > 0) {
      const chunkWords = convertUnder1000(chunk);
      const scale = scales[i];
      if (scale) {
        parts.push(`${chunkWords} ${scale}`);
      } else {
        parts.push(chunkWords);
      }
    }
  }

  // Join parts with spaces
  return parts.join(" ");
}

