  return result;
};
// @openarc:end atbashCipher.decode

export function encode(plainText: string): string {
  const alphabet = "abcdefghijklmnopqrstuvwxyz";
  const map = new Map<string, string>();

  for (let i = 0; i < alphabet.length; i++) {
    map.set(alphabet[i], alphabet[alphabet.length - 1 - i]);
  }

  let result = "";
  let count = 0;

  for (const char of plainText.toLowerCase()) {
    if (char >= "a" && char <= "z") {
      if (count > 0 && count % 5 === 0) {
        result += " ";
      }
      result += map.get(char)!;
      count++;
    } else if (char >= "0" && char <= "9") {
      if (count > 0 && count % 5 === 0) {
        result += " ";
      }
      result += char;
      count++;
    }
    // Ignore punctuation and whitespace
  }

  return result;
}

export function decode(cipherText: string): string {
  const alphabet = "abcdefghijklmnopqrstuvwxyz";
  const map = new Map<string, string>();

  for (let i = 0; i < alphabet.length; i++) {
    map.set(alphabet[i], alphabet[alphabet.length - 1 - i]);
  }

  let result = "";

  for (const char of cipherText.toLowerCase()) {
    if (char >= "a" && char <= "z") {
      result += map.get(char)!;
    } else if (char >= "0" && char <= "9") {
      result += char;
    }
    // Ignore spaces and punctuation
  }

  return result;
}

