// @openarc:begin knapsack.maximumValue
export const maximumValue: MaximumValueFn = (input) => {
  const n = input.items.length;
  if (n === 0) return 0;
  const weights = input.items.map(i => i.weight);
  const values = input.items.map(i => i.value);
  const maxWeight = input.maximumWeight;
  const dp = new Array(n + 1).fill(null).map(() => new Array(maxWeight + 1).fill(0));
  for (let i = 1; i <= n; i++) {
    const w = weights[i - 1];
    const v = values[i - 1];
    for (let j = 0; j <= maxWeight; j++) {
      dp[i][j] = dp[i - 1][j];
      if (j >= w) {
        dp[i][j] = Math.max(dp[i][j], dp[i - 1][j - w] + v);
      }
    }
  }
  return dp[n][maxWeight];
};
// @openarc:end knapsack.maximumValue

export interface Item { weight: number; value: number }

export function maximumValue(input: { maximumWeight: number; items: Item[] }): number {
  const { maximumWeight, items } = input;

  // Handle edge cases
  if (maximumWeight <= 0 || items.length === 0) {
    return 0;
  }

  const n = items.length;
  // dp[i][w] represents the maximum value achievable with the first i items and weight limit w
  // We use a 1D array to optimize space complexity to O(maximumWeight)
  const dp = new Array(maximumWeight + 1).fill(0);

  for (const item of items) {
    const weight = item.weight;
    const value = item.value;

    // Traverse backwards to avoid using the same item multiple times for the same weight limit in one iteration
    for (let w = maximumWeight; w >= weight; w--) {
      dp[w] = Math.max(dp[w], dp[w - weight] + value);
    }
  }

  return dp[maximumWeight];
}

