export const convert: ConvertFn = (grid) => {
  const lines = grid.split('
');
  if (lines.length % 4 !== 0) throw new Error('Invalid grid size');
  const numLines = lines.length / 4;
  const firstLine = lines[0];
  if (firstLine.length % 3 !== 0) throw new Error('Invalid grid width');
  const numCols = firstLine.length / 3;
  const patterns = [
      [' _ ', '| |', '|_|', '   '],
      ['   ', '  |', '  |', '   '],
      [' _ ', ' _|', '|_ ', '   '],
      [' _ ', ' _|', ' _|', '   '],
      ['   ', '|_|', '  |', '   '],
      [' _ ', '|_ ', ' _|', '   '],
      [' _ ', '  |', '  |', '   '],
      [' _ ', '|_|', '|_|', '   '],
      [' _ ', '| |', '|_|', '   '],
      [' _ ', '|_|', ' _|', '   ']
    ];
  const result: string[] = [];
  for (let i = 0; i < numLines; i++) {
      const lineNum = i * 4;
      const row0 = lines[lineNum];
      const row1 = lines[lineNum + 1];
      const row2 = lines[lineNum + 2];
      const row3 = lines[lineNum + 3];
      const lineResult: string[] = [];
      for (let j = 0; j < numCols; j++) {
        const col0 = row0.slice(j * 3, j * 3 + 3);
        const col1 = row1.slice(j * 3, j * 3 + 3);
        const col2 = row2.slice(j * 3, j * 3 + 3);
        const col3 = row3.slice(j * 3, j * 3 + 3);
        const pattern = [col0, col1, col2, col3];
        let found = -1;
        for (let k = 0; k < patterns.length; k++) {
          if (JSON.stringify(pattern) === JSON.stringify(patterns[k])) {
            found = k;
            break;
          }
        }
        if (found === -1) {
          lineResult.push('?');
        } else {
          lineResult.push(found.toString());
        }
      }
      result.push(lineResult.join(''));
    }
  return result.join(',');
};
// @openarc:end ocrNumbers.convert

export function convert(grid: string): string {
  const lines = grid.split("\n");

  // Validate line count
  if (lines.length !== 4) {
    throw new Error("Incorrect number of lines");
  }

  // Validate each line length is a multiple of 3
  for (const line of lines) {
    if (line.length % 3 !== 0) {
      throw new Error("Incorrect line length");
    }
  }

  const numCols = lines[0].length;
  const numDigits = numCols / 3;

  // Validate all lines have the same length
  for (let i = 1; i < lines.length; i++) {
    if (lines[i].length !== numCols) {
      throw new Error("Inconsistent line lengths");
    }
  }

  const digitPatterns: Record<string, string> = {
    " _ | ||_|": "0",
    "     |  |": "1",
    " _  _||_ ": "2",
    " _  _| _|": "3",
    "   |_|  |": "4",
    " _ |_  _|": "5",
    " _ |_ |_|": "6",
    " _   |  |": "7",
    " _ |_||_|": "8",
    " _ |_| _|": "9",
  };

  const result: string[] = [];

  for (let d = 0; d < numDigits; d++) {
    let pattern = "";
    for (let r = 0; r < 3; r++) {
      const rowStart = d * 3;
      const rowEnd = rowStart + 3;
      pattern += lines[r].substring(rowStart, rowEnd);
    }

    const recognized = digitPatterns[pattern];
    if (recognized !== undefined) {
      result.push(recognized);
    } else {
      result.push("?");
    }
  }

  return result.join("");
}

