// @openarc:begin primeFactors.calculatePrimeFactors
export const calculatePrimeFactors: CalculatePrimeFactorsFn = (n) => {
  if (n <= 1) return [];
    const factors: number[] = [];
    let divisor = 2;
    while (n > 1) {
      while (n % divisor === 0) {
        factors.push(divisor);
        n = n / divisor;
      }
      divisor++;
    }
    return factors;
};
