// @openarc:begin proteinTranslation.translate
export const translate: TranslateFn = (rna) => {
  const codonMap: Record<string, string> = {
    AUG: 'Methionine',
    UUU: 'Phenylalanine',
    UUC: 'Phenylalanine',
    UUA: 'Leucine',
    UUG: 'Leucine',
    UCU: 'Serine',
    UCC: 'Serine',
    UCA: 'Serine',
    UCG: 'Serine',
    UAU: 'Tyrosine',
    UAC: 'Tyrosine',
    UGU: 'Cysteine',
    UGC: 'Cysteine',
    UGG: 'Tryptophan',
    UAA: 'STOP',
    UAG: 'STOP',
    UGA: 'STOP'
  };
  const proteins: string[] = [];
  for (let i = 0; i < rna.length; i += 3) {
      const codon = rna.slice(i, i + 3);
      const aminoAcid = codonMap[codon];
      if (aminoAcid === 'STOP') {
        break;
      }
      if (aminoAcid) {
        proteins.push(aminoAcid);
      }
    }
  return proteins;
};
// @openarc:end proteinTranslation.translate

export function translate(rna: string): string[] {
  const codonMap: Record<string, string> = {
    AUG: "Methionine",
    UUU: "Phenylalanine",
    UUC: "Phenylalanine",
    UUA: "Leucine",
    UUG: "Leucine",
    UCU: "Serine",
    UCC: "Serine",
    UCA: "Serine",
    UCG: "Serine",
    UAU: "Tyrosine",
    UAC: "Tyrosine",
    UGU: "Cysteine",
    UGC: "Cysteine",
    UGG: "Tryptophan",
    UAA: "STOP",
    UAG: "STOP",
    UGA: "STOP",
  };

  const proteins: string[] = [];
  const length = rna.length;

  for (let i = 0; i < length; i += 3) {
    if (i + 3 > length) {
      throw new Error("Invalid codon");
    }

    const codon = rna.slice(i, i + 3);
    const aminoAcid = codonMap[codon];

    if (aminoAcid === undefined) {
      throw new Error("Invalid codon");
    }

    if (aminoAcid === "STOP") {
      break;
    }

    proteins.push(aminoAcid);
  }

  return proteins;
}

