export type FamilyTree = Record<string, string[]>;

export function degreesOfSeparation(
  familyTree: FamilyTree,
  personA: string,
  personB: string
): number {
  if (personA === personB) {
    return 0;
  }

  // Build a bidirectional graph from the family tree.
  // The input gives children for each parent. We add edges from parent to child
  // and from child to parent.
  const graph = new Map<string, Set<string>>();

  const addEdge = (u: string, v: string) => {
    if (!graph.has(u)) graph.set(u, new Set());
    if (!graph.has(v)) graph.set(v, new Set());
    graph.get(u)!.add(v);
    graph.get(v)!.add(u);
  };

  for (const [parent, children] of Object.entries(familyTree)) {
    for (const child of children) {
      addEdge(parent, child);
    }
  }

  // Ensure both persons exist in the graph (even if they have no children listed)
  if (!graph.has(personA)) graph.set(personA, new Set());
  if (!graph.has(personB)) graph.set(personB, new Set());

  // BFS to find the shortest path
  const queue: [string, number][] = [[personA, 0]];
  const visited = new Set<string>([personA]);

  while (queue.length > 0) {
    const [current, distance] = queue.shift()!;

    if (current === personB) {
      return distance;
    }

    const neighbors = graph.get(current);
    if (neighbors) {
      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          visited.add(neighbor);
          queue.push([neighbor, distance + 1]);
        }
      }
    }
  }

  // No path found
  return -1;
}

