// @openarc:begin resistorColorTrio.decodedResistorValue
export const decodedResistorValue: DecodedResistorValueFn = (colors) => {
  const colorCode: Record<string, number> = { black: 0, brown: 1, red: 2, orange: 3, yellow: 4, green: 5, blue: 6, violet: 7, grey: 8, white: 9 };
  const [first, second, third] = colors;
  const value = (colorCode[first] * 10 + colorCode[second]) * Math.pow(10, colorCode[third]);
  if (value % 1000 === 0) return `${value / 1000} kiloohms`;
  if (value % 100 === 0) return `${value / 100} hundred ohms`;
  return `${value} ohms`;
};
// @openarc:end resistorColorTrio.decodedResistorValue

export function decodedResistorValue(colors: string[]): string {
  const colorMap: Record<string, number> = {
    black: 0,
    brown: 1,
    red: 2,
    orange: 3,
    yellow: 4,
    green: 5,
    blue: 6,
    violet: 7,
    grey: 8,
    white: 9,
  };

  if (colors.length !== 3 || !colors.every((c) => c in colorMap)) {
    throw new Error("Invalid color combination");
  }

  const firstDigit = colorMap[colors[0]];
  const secondDigit = colorMap[colors[1]];
  const zeros = colorMap[colors[2]];

  const mainValue = firstDigit * 10 + secondDigit;
  let value = mainValue * (10 ** zeros);

  let unit = "ohms";
  if (value >= 1000000000) {
    value = value / 1000000000;
    unit = "gigaohms";
  } else if (value >= 1000000) {
    value = value / 1000000;
    unit = "megaohms";
  } else if (value >= 1000) {
    value = value / 1000;
    unit = "kiloohms";
  }

  // Only show decimal part if it's not a whole number
  if (Number.isInteger(value)) {
    return `${value} ${unit}`;
  } else {
    // Remove trailing zeros after decimal point and the decimal point itself if unnecessary
    const formattedValue = value.toFixed(1).replace(/\.?0+$/, "");
    return `${formattedValue} ${unit}`;
  }
}

