// @openarc:begin romanNumerals.toRoman
export const toRoman: ToRomanFn = (n) => {
  const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  const symbols = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let result = "";
  for (let i = 0; i < values.length; i++) {
    while (n >= values[i]) {
      result += symbols[i];
      n -= values[i];
    }
  }
  return result;
};
// @openarc:end romanNumerals.toRoman

export function toRoman(n: number): string {
  if (n === undefined || n === NaN || n === Infinity || n < 1 || n > 3999) {
    throw new Error("Input must be an integer between 1 and 3999");
  }

  const values = [
    1000,
    900,
    500,
    400,
    100,
    90,
    50,
    40,
    10,
    9,
    5,
    4,
    1
  ];

  const numerals = [
    "M",
    "CM",
    "D",
    "CD",
    "C",
    "XC",
    "L",
    "XL",
    "X",
    "IX",
    "V",
    "IV",
    "I"
  ];

  let result = "";
  let index = 0;

  while (n > 0) {
    const count = Math.floor(n / values[index]);
    if (count > 0) {
      result += numerals[index].repeat(count);
      n -= values[index] * count;
    } else {
      index++;
    }
  }

  return result;
}

