// @openarc:begin runLengthEncoding.encode
export const encode: EncodeFn = (plain) => {
  let result = '';
    let count = 1;
    for (let i = 0; i < plain.length; i++) {
      if (i + 1 < plain.length && plain[i] === plain[i + 1]) {
        count++;
      } else {
        result += count > 1 ? count + plain[i] : plain[i];
        count = 1;
      }
    }
    return result;
};
// @openarc:end runLengthEncoding.encode

