// @openarc:begin runLengthEncoding.decode
export const decode: DecodeFn = (encoded) => {
  let result = '';
    for (let i = 0; i < encoded.length; i++) {
      const char = encoded[i];
      if (/[0-9]/.test(char)) {
        let count = 0;
        while (i < encoded.length && /[0-9]/.test(encoded[i])) {
          count = count * 10 + parseInt(encoded[i++], 10);
        }
        const nextChar = encoded[i];
        for (let j = 0; j < count; j++) {
          result += nextChar;
        }
      } else {
        result += char;
      }
    }
    return result;
};
// @openarc:end runLengthEncoding.decode

export function encode(plain: string): string {
  if (plain.length === 0) return "";

  let result = "";
  let count = 1;

  for (let i = 0; i < plain.length; i++) {
    const currentChar = plain[i];
    const nextChar = plain[i + 1];

    if (currentChar === nextChar) {
      count++;
    } else {
      if (count > 1) {
        result += `${count}${currentChar}`;
      } else {
        result += currentChar;
      }
      count = 1;
    }
  }

  // Append the last run
  if (count > 1) {
    result += `${count}${plain[plain.length - 1]}`;
  } else {
    result += plain[plain.length - 1];
  }

  return result;
}

export function decode(encoded: string): string {
  if (encoded.length === 0) return "";

  let result = "";
  let i = 0;

  while (i < encoded.length) {
    const char = encoded[i];

    // Check if the current character is a digit
    if (/\d/.test(char)) {
      let numberStr = char;
      i++;

      // Collect all consecutive digits to form the full number
      while (i < encoded.length && /\d/.test(encoded[i])) {
        numberStr += encoded[i];
        i++;
      }

      const count = parseInt(numberStr, 10);
      const nextChar = encoded[i];

      // Append the character 'count' times
      for (let j = 0; j < count; j++) {
        result += nextChar;
      }
    } else {
      // If it's not a digit, it's a character with a count of 1
      result += char;
      i++;
    }
  }

  return result;
}

