// @openarc:begin sieve.primes
export const primes: PrimesFn = (limit) => {
  limit = limit;
  if (limit < 2) return [];
  const isPrime = new Array(limit + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;
  for (let i = 2; i * i <= limit; i++) {
    if (isPrime[i]) {
      for (let j = i * i; j <= limit; j += i) {
        isPrime[j] = false;
      }
    }
  }
  const result: number[] = [];
  for (let i = 2; i <= limit; i++) {
    if (isPrime[i]) {
      result.push(i);
    }
  }
  return result;
};
// @openarc:end sieve.primes

export function primes(limit: number): number[] {
  if (limit < 2) {
    return [];
  }

  // Create a boolean array "isPrime[0..limit]" and initialize
  // all entries it as true. A value in isPrime[i] will
  // finally be false if i is Not a prime, else true.
  const isPrime = new Array(limit + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;

  for (let p = 2; p * p <= limit; p++) {
    // If isPrime[p] is not changed, then it is a prime
    if (isPrime[p]) {
      // Update all multiples of p
      for (let multiple = p * p; multiple <= limit; multiple += p) {
        isPrime[multiple] = false;
      }
    }
  }

  // Collect all prime numbers
  const result: number[] = [];
  for (let p = 2; p <= limit; p++) {
    if (isPrime[p]) {
      result.push(p);
    }
  }

  return result;
}
